1	import type { MetadataRoute } from "next";
2	import { db } from "@/lib/db";
3	
4	const APP_URL = process.env.APP_URL ?? "https://revsports.ca";
5	
6	export const dynamic = "force-dynamic";
7	
8	export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
9	  const now = new Date();
10	
11	  const staticRoutes: Array<{ path: string; priority: number; freq: MetadataRoute.Sitemap[number]["changeFrequency"] }> = [
12	    { path: "", priority: 1.0, freq: "weekly" },
13	    { path: "/features", priority: 0.8, freq: "monthly" },
14	    { path: "/pricing", priority: 0.9, freq: "weekly" },
15	    { path: "/vps", priority: 0.8, freq: "monthly" },
16	    { path: "/domains", priority: 0.8, freq: "monthly" },
17	    { path: "/compare", priority: 0.7, freq: "monthly" },
18	    { path: "/vps-vs-digitalocean", priority: 0.7, freq: "monthly" },
19	    { path: "/vps-vs-hostinger", priority: 0.7, freq: "monthly" },
20	    { path: "/about", priority: 0.5, freq: "monthly" },
21	    { path: "/contact", priority: 0.5, freq: "monthly" },
22	    { path: "/blog", priority: 0.7, freq: "weekly" },
23	    { path: "/status", priority: 0.4, freq: "daily" },
24	    { path: "/legal/terms", priority: 0.3, freq: "yearly" },
25	    { path: "/legal/privacy", priority: 0.3, freq: "yearly" },
26	    { path: "/legal/aup", priority: 0.3, freq: "yearly" },
27	    { path: "/legal/sla", priority: 0.3, freq: "yearly" },
28	  ];
29	
30	  const entries: MetadataRoute.Sitemap = staticRoutes.map((r) => ({
31	    url: `${APP_URL}${r.path}`,
32	    lastModified: now,
33	    changeFrequency: r.freq,
34	    priority: r.priority,
35	  }));
36	
37	  // Published blog posts (model may not be migrated yet — access defensively).
38	  try {
39	    const blogModel = (db as unknown as { blogPost?: { findMany: (a: unknown) => Promise<Array<{ slug: string; updatedAt: Date }>> } }).blogPost;
40	    const posts = blogModel
41	      ? await blogModel.findMany({
42	          where: { published: true },
43	          select: { slug: true, updatedAt: true },
44	          orderBy: { publishedAt: "desc" },
45	        })
46	      : [];
47	    for (const p of posts) {
48	      entries.push({
49	        url: `${APP_URL}/blog/${p.slug}`,
50	        lastModified: p.updatedAt,
51	        changeFrequency: "monthly",
52	        priority: 0.6,
53	      });
54	    }
55	  } catch {
56	    // blogPost model not migrated yet — skip.
57	  }
58	
59	  return entries;
60	}
