68	export function MarketingHeader() {
69	  const pathname = usePathname();
70	  const [open, setOpen] = useState(false); // mobile drawer
71	  const [menu, setMenu] = useState<null | "products" | "company">(null); // desktop dropdown
72	  const [scrolled, setScrolled] = useState(false);
73	  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
74	
75	  useEffect(() => {
76	    const onScroll = () => setScrolled(window.scrollY > 8);
77	    onScroll();
78	    window.addEventListener("scroll", onScroll, { passive: true });
79	    return () => window.removeEventListener("scroll", onScroll);
80	  }, []);
81	
82	  useEffect(() => {
83	    setOpen(false);
84	    setMenu(null);
85	  }, [pathname]);
86	
87	  // Hover-intent: brief close delay so diagonal mouse travel to the panel doesn't drop it.
88	  const openMenu = (m: "products" | "company") => {
89	    if (closeTimer.current) clearTimeout(closeTimer.current);
90	    setMenu(m);
91	  };
92	  const scheduleClose = () => {
93	    if (closeTimer.current) clearTimeout(closeTimer.current);
94	    closeTimer.current = setTimeout(() => setMenu(null), 120);
95	  };
96	
97	  return (
98	    <header
99	      className={`sticky top-0 z-50 border-b transition-colors duration-300 ${
100	        scrolled || menu ? "border-white/[0.06] bg-navy-950/85 backdrop-blur-xl" : "border-transparent bg-transparent"
101	      }`}
102	      onMouseLeave={scheduleClose}
103	    >
104	      <div className="rail flex h-[72px] items-center justify-between">
105	        <Link href="/" aria-label="Nxeon home" className="shrink-0">
106	          <NxLogo id="hdr" size={44} />
107	        </Link>
108	
109	        {/* Desktop nav */}
110	        <nav className="hidden items-center gap-1 lg:flex">
111	          <button
112	            className={`nav-trigger ${menu === "products" ? "is-open" : ""}`}
