import { NextResponse } from "next/server";
import { Resolver } from "node:dns/promises";
import { toolRateLimit, jsonError, readField } from "@/lib/tools/api";
import { extractHost, isPlausibleHost } from "@/lib/tools/net-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * DNS lookup — resolves A / AAAA / MX / TXT / NS / CNAME / SOA for a domain via
 * node:dns. Public DNS only (no connections are made to the target), but we still
 * validate the hostname and cap output. Rate-limited per IP.
 */

const TIMEOUT_MS = 5000;
const TYPES = ["A", "AAAA", "MX", "TXT", "NS", "CNAME", "SOA"] as const;
type RecordType = (typeof TYPES)[number];

function withTimeout<T>(p: Promise<T>): Promise<T> {
  return Promise.race([
    p,
    new Promise<T>((_, rej) => setTimeout(() => rej(new Error("timeout")), TIMEOUT_MS)),
  ]);
}

export async function POST(req: Request) {
  const limited = toolRateLimit(req, "dns", { max: 30, windowMs: 60_000 });
  if (limited) return limited;

  const raw = await readField(req, "domain");
  const host = extractHost(raw);
  if (!host || !isPlausibleHost(host)) return jsonError("Enter a valid domain name.");
  if (host === "localhost") return jsonError("That host is not allowed.");

  const resolver = new Resolver({ timeout: TIMEOUT_MS, tries: 2 });

  async function resolveType(type: RecordType): Promise<string[]> {
    try {
      switch (type) {
        case "A":
          return await withTimeout(resolver.resolve4(host!));
        case "AAAA":
          return await withTimeout(resolver.resolve6(host!));
        case "MX": {
          const mx = await withTimeout(resolver.resolveMx(host!));
          return mx
            .sort((a, b) => a.priority - b.priority)
            .map((r) => `${r.priority}\t${r.exchange}`);
        }
        case "TXT": {
          const txt = await withTimeout(resolver.resolveTxt(host!));
          return txt.map((chunks) => chunks.join(""));
        }
        case "NS":
          return await withTimeout(resolver.resolveNs(host!));
        case "CNAME":
          return await withTimeout(resolver.resolveCname(host!));
        case "SOA": {
          const soa = await withTimeout(resolver.resolveSoa(host!));
          return [
            `${soa.nsname} ${soa.hostmaster} serial=${soa.serial} refresh=${soa.refresh} retry=${soa.retry} expire=${soa.expire} minttl=${soa.minttl}`,
          ];
        }
      }
    } catch {
      return [];
    }
  }

  try {
    const settled = await Promise.all(
      TYPES.map(async (t) => [t, (await resolveType(t)).slice(0, 100)] as const),
    );
    const records: Record<string, string[]> = {};
    for (const [t, vals] of settled) records[t] = vals;
    const total = Object.values(records).reduce((n, v) => n + v.length, 0);
    if (total === 0) return jsonError("No DNS records found (the domain may not exist).", 404);
    return NextResponse.json({ ok: true, host, records });
  } catch {
    return jsonError("DNS lookup failed.", 502);
  }
}

import { NextResponse } from "next/server";
import net from "node:net";
import { toolRateLimit, jsonError, readField } from "@/lib/tools/api";
import { extractHost, isPlausibleHost } from "@/lib/tools/net-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * WHOIS lookup — raw TCP (port 43) WHOIS client with IANA referral following.
 *
 * We query whois.iana.org first, read the "refer:" / "whois:" server for the TLD,
 * then re-query that authoritative server. No third-party API, no dependency.
 * The WHOIS servers we connect to are a fixed allowlist (IANA + the referred host,
 * itself validated as a public hostname), timeouts ≤5s, output capped.
 */

const PORT = 43;
const TIMEOUT_MS = 5000;
const MAX_BYTES = 64 * 1024;

/** One raw WHOIS query to `server:43` for `query`. Resolves with the text body. */
function whoisQuery(server: string, query: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    const socket = net.createConnection({ host: server, port: PORT });
    socket.setTimeout(TIMEOUT_MS);

    const done = (err?: Error) => {
      socket.destroy();
      if (err) reject(err);
      else resolve(Buffer.concat(chunks).toString("utf8"));
    };

    socket.on("connect", () => socket.write(`${query}\r\n`));
    socket.on("data", (d) => {
      size += d.length;
      if (size > MAX_BYTES) {
        chunks.push(d.subarray(0, Math.max(0, MAX_BYTES - (size - d.length))));
        done();
        return;
      }
      chunks.push(d);
    });
    socket.on("end", () => done());
    socket.on("timeout", () => done(new Error("WHOIS server timed out.")));
    socket.on("error", (e) => done(e));
  });
}

/** Pull a referral WHOIS server (refer:/whois:) out of an IANA response. */
function parseReferral(text: string): string | null {
  const m = text.match(/^(?:refer|whois):\s*([a-z0-9.-]+)\s*$/im);
  return m ? m[1].toLowerCase() : null;
}

/** Extract a few well-known fields for the summary card. */
function summarize(text: string) {
  const grab = (labels: string[]): string[] => {
    const out: string[] = [];
    for (const line of text.split(/\r?\n/)) {
      const m = line.match(/^\s*([^:]+):\s*(.+?)\s*$/);
      if (!m) continue;
      const key = m[1].trim().toLowerCase();
      if (labels.some((l) => key === l || key.startsWith(l))) out.push(m[2].trim());
    }
    return [...new Set(out)];
  };
  return {
    registrar: grab(["registrar", "sponsoring registrar"])[0] ?? null,
    created: grab(["creation date", "created", "registered on", "registration time"])[0] ?? null,
    updated: grab(["updated date", "last updated", "last modified"])[0] ?? null,
    expires: grab(["registry expiry date", "expiration date", "expiry date", "expires", "expire"])[0] ?? null,
    status: grab(["domain status", "status"]).slice(0, 6),
    nameservers: grab(["name server", "nserver", "nameserver"]).map((n) => n.toLowerCase()).slice(0, 8),
  };
}

export async function POST(req: Request) {
  const limited = toolRateLimit(req, "whois", { max: 15, windowMs: 60_000 });
  if (limited) return limited;

  const raw = await readField(req, "domain");
  const host = extractHost(raw);
  if (!host || !isPlausibleHost(host) || net.isIP(host)) {
    return jsonError("Enter a valid domain name (e.g. example.com).");
  }
  if (host === "localhost" || !host.includes(".")) {
    return jsonError("Enter a fully-qualified domain name.");
  }

  try {
    // 1) Ask IANA which server is authoritative for this TLD.
    const ianaText = await whoisQuery("whois.iana.org", host);
    const referral = parseReferral(ianaText);

    let text = ianaText;
    let server = "whois.iana.org";
    // 2) Re-query the referred registry/registrar server if it's a valid public host.
    if (referral && isPlausibleHost(referral) && !net.isIP(referral) && referral !== "whois.iana.org") {
      try {
        const registryText = await whoisQuery(referral, host);
        if (registryText.trim().length > 0) {
          text = registryText;
          server = referral;
        }
      } catch {
        /* fall back to the IANA body */
      }
    }

    if (!text.trim()) return jsonError("No WHOIS data returned for that domain.", 404);

    return NextResponse.json({
      ok: true,
      host,
      server,
      summary: summarize(text),
      raw: text.slice(0, MAX_BYTES),
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : "WHOIS lookup failed.";
    return jsonError(msg, 502);
  }
}

import { NextResponse } from "next/server";
import net from "node:net";
import { toolRateLimit, jsonError, clientIp } from "@/lib/tools/api";
import { checkRateLimit } from "@/lib/rate-limit";
import { extractHost, resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * TCP port checker — opens a TCP connection to host:port and reports open/closed
 * plus connect latency. The host is SSRF-guarded (resolved to a public IP; private
 * / loopback / reserved targets are rejected) and we connect to the vetted IP,
 * never re-resolving. Port must be 1-65535. Timeout ≤5s, rate-limited per IP.
 */

const TIMEOUT_MS = 5000;

const COMMON: Record<number, string> = {
  20: "FTP-DATA", 21: "FTP", 22: "SSH", 23: "Telnet", 25: "SMTP", 53: "DNS",
  80: "HTTP", 110: "POP3", 143: "IMAP", 443: "HTTPS", 465: "SMTPS", 587: "SMTP",
  993: "IMAPS", 995: "POP3S", 3306: "MySQL", 3389: "RDP", 5432: "PostgreSQL",
  6379: "Redis", 8080: "HTTP-alt", 8443: "HTTPS-alt", 27017: "MongoDB",
};

function tryConnect(ip: string, port: number): Promise<{ open: boolean; latencyMs: number }> {
  return new Promise((resolve) => {
    const started = Date.now();
    const socket = new net.Socket();
    let settled = false;
    const finish = (open: boolean) => {
      if (settled) return;
      settled = true;
      socket.destroy();
      resolve({ open, latencyMs: Date.now() - started });
    };
    socket.setTimeout(TIMEOUT_MS);
    socket.once("connect", () => finish(true));
    socket.once("timeout", () => finish(false));
    socket.once("error", () => finish(false));
    socket.connect(port, ip);
  });
}

export async function POST(req: Request) {
  const limited = toolRateLimit(req, "port", { max: 20, windowMs: 60_000 });
  if (limited) return limited;

  const body = (await req.json().catch(() => ({}))) as { host?: unknown; port?: unknown };
  const host = extractHost(typeof body.host === "string" ? body.host : "");
  const port = Number(body.port);

  if (!host) return jsonError("Enter a valid host.");
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return jsonError("Port must be an integer between 1 and 65535.");
  }

  try {
    const { host: resolved, addresses } = await resolvePublicHost(host);
    const ip = addresses[0];
    // Extra per-target throttle so we can't be used to sweep one host's ports.
    const sweep = checkRateLimit(`portsweep:${clientIp(req)}:${resolved}`, {
      max: 30,
      windowMs: 60_000,
    });
    if (!sweep.ok) return jsonError(`Too many checks against that host. Try again in ${sweep.retryAfterSec}s.`, 429);

    const result = await tryConnect(ip, port);
    return NextResponse.json({
      ok: true,
      host: resolved,
      ip,
      port,
      service: COMMON[port] ?? null,
      open: result.open,
      latencyMs: result.open ? result.latencyMs : null,
    });
  } catch (e) {
    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
    return jsonError("Port check failed.", 502);
  }
}

import { NextResponse } from "next/server";
import tls from "node:tls";
import type { PeerCertificate, DetailedPeerCertificate } from "node:tls";
import { toolRateLimit, jsonError, readField } from "@/lib/tools/api";
import { extractHost, resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * SSL/TLS certificate checker — TLS-connects to host:443 (SNI = host, connecting
 * to a vetted public IP) and reports issuer, subject, SAN, validity window, days
 * to expiry, and the chain. rejectUnauthorized is off so we can still inspect
 * expired / self-signed / mismatched certs and tell the user what's wrong.
 */

const TIMEOUT_MS = 5000;
const DEFAULT_PORT = 443;

function name(obj: Record<string, string> | undefined): string | null {
  if (!obj) return null;
  return obj.CN || obj.O || Object.values(obj)[0] || null;
}

type ChainLink = { subject: string | null; issuer: string | null; validTo: string };

function collectChain(cert: DetailedPeerCertificate): ChainLink[] {
  const out: ChainLink[] = [];
  const seen = new Set<string>();
  let cur: DetailedPeerCertificate | undefined = cert;
  while (cur && cur.fingerprint && !seen.has(cur.fingerprint)) {
    seen.add(cur.fingerprint);
    out.push({ subject: name(cur.subject), issuer: name(cur.issuer), validTo: cur.valid_to });
    if (cur.issuerCertificate && cur.issuerCertificate.fingerprint !== cur.fingerprint) {
      cur = cur.issuerCertificate;
    } else {
      break;
    }
    if (out.length >= 6) break;
  }
  return out;
}

export async function POST(req: Request) {
  const limited = toolRateLimit(req, "ssl", { max: 20, windowMs: 60_000 });
  if (limited) return limited;

  const raw = await readField(req, "host");
  const host = extractHost(raw);
  if (!host) return jsonError("Enter a valid host (e.g. example.com).");

  try {
    const { host: servername, addresses } = await resolvePublicHost(host);
    const ip = addresses[0];

    const result = await new Promise<{ cert: DetailedPeerCertificate; authorized: boolean; error: string | null; protocol: string | null }>(
      (resolve, reject) => {
        const socket = tls.connect(
          {
            host: ip,
            port: DEFAULT_PORT,
            servername,
            rejectUnauthorized: false,
            timeout: TIMEOUT_MS,
          },
          () => {
            const cert = socket.getPeerCertificate(true);
            const protocol = socket.getProtocol();
            const authorized = socket.authorized;
            const error = socket.authorizationError ? String(socket.authorizationError) : null;
            socket.destroy();
            if (!cert || Object.keys(cert).length === 0) {
              reject(new Error("No certificate was presented."));
              return;
            }
            resolve({ cert, authorized, error, protocol });
          },
        );
        socket.setTimeout(TIMEOUT_MS);
        socket.once("timeout", () => {
          socket.destroy();
          reject(new Error("Connection timed out."));
        });
        socket.once("error", (e) => {
          socket.destroy();
          reject(e);
        });
      },
    );

    const cert: PeerCertificate = result.cert;
    const validFrom = new Date(cert.valid_from);
    const validTo = new Date(cert.valid_to);
    const now = Date.now();
    const daysToExpiry = Math.floor((validTo.getTime() - now) / 86_400_000);
    const san = (cert.subjectaltname ?? "")
      .split(",")
      .map((s) => s.trim().replace(/^DNS:/, ""))
      .filter(Boolean)
      .slice(0, 30);

    return NextResponse.json({
      ok: true,
      host: servername,
      subject: name(cert.subject as Record<string, string>),
      issuer: name(cert.issuer as Record<string, string>),
      altNames: san,
      validFrom: validFrom.toISOString(),
      validTo: validTo.toISOString(),
      daysToExpiry,
      expired: daysToExpiry < 0,
      valid: result.authorized,
      validationError: result.error,
      protocol: result.protocol,
      serialNumber: cert.serialNumber ?? null,
      chain: collectChain(result.cert),
    });
  } catch (e) {
    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
    const msg = e instanceof Error ? e.message : "SSL check failed.";
    return jsonError(`Could not complete TLS handshake: ${msg}`, 502);
  }
}

import { NextResponse } from "next/server";
import { toolRateLimit, jsonError, readField } from "@/lib/tools/api";
import { resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * HTTP header inspector — fetches a URL and returns the status + response headers.
 *
 * SSRF guard: only http/https, the target host is resolved and every address must
 * be public (private / loopback / reserved → rejected). Redirects are NOT followed
 * (redirect: "manual") so we can't be bounced to an internal endpoint — we just
 * report the Location. 5s timeout, header values capped, no body is returned.
 */

const TIMEOUT_MS = 5000;

export async function POST(req: Request) {
  const limited = toolRateLimit(req, "http-headers", { max: 20, windowMs: 60_000 });
  if (limited) return limited;

  let input = await readField(req, "url", 2048);
  if (!input) return jsonError("Enter a URL.");
  if (!/^https?:\/\//i.test(input)) input = `https://${input}`;

  let url: URL;
  try {
    url = new URL(input);
  } catch {
    return jsonError("That doesn't look like a valid URL.");
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    return jsonError("Only http:// and https:// URLs are supported.");
  }

  try {
    await resolvePublicHost(url.hostname); // throws BlockedHostError on private/reserved

    const res = await fetch(url.toString(), {
      method: "GET",
      redirect: "manual",
      signal: AbortSignal.timeout(TIMEOUT_MS),
      headers: { "user-agent": "Nxeon-Tools/1.0 (+https://nxeon.com/tools/http-headers)" },
    });

    const headers: [string, string][] = [];
    res.headers.forEach((value, key) => {
      headers.push([key, value.slice(0, 2048)]);
    });
    headers.sort((a, b) => a[0].localeCompare(b[0]));

    // Don't read the body — free the connection immediately.
    try {
      await res.body?.cancel();
    } catch {
      /* ignore */
    }

    const redirected = res.status >= 300 && res.status < 400;
    return NextResponse.json({
      ok: true,
      url: url.toString(),
      finalHost: url.hostname,
      status: res.status,
      statusText: res.statusText,
      redirect: redirected ? res.headers.get("location") : null,
      headers: headers.slice(0, 80),
    });
  } catch (e) {
    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
    if (e instanceof Error && e.name === "TimeoutError") return jsonError("Request timed out.", 504);
    return jsonError("Could not fetch that URL.", 502);
  }
}

import { NextResponse } from "next/server";
import { reverse } from "node:dns/promises";
import net from "node:net";
import { clientIp } from "@/lib/tools/api";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * "What's my IP" — echoes the caller's public IP (from x-forwarded-for, set by
 * nginx) plus a reverse-DNS (PTR) lookup and a couple of request hints. No user
 * input, so no SSRF surface. Handy from a browser or `curl`.
 */

export async function GET(req: Request) {
  const ip = clientIp(req);
  const kind = net.isIP(ip);

  let ptr: string | null = null;
  if (kind !== 0) {
    try {
      const names = await Promise.race([
        reverse(ip),
        new Promise<string[]>((_, rej) => setTimeout(() => rej(new Error("timeout")), 3000)),
      ]);
      ptr = names[0] ?? null;
    } catch {
      ptr = null;
    }
  }

  return NextResponse.json({
    ok: true,
    ip,
    version: kind === 4 ? "IPv4" : kind === 6 ? "IPv6" : "unknown",
    reverseDns: ptr,
    userAgent: (req.headers.get("user-agent") ?? "").slice(0, 400) || null,
    forwardedFor: req.headers.get("x-forwarded-for") ?? null,
  });
}

