  async function run(e: React.FormEvent) {
    e.preventDefault();
    if (!url.trim()) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/tools/http-headers", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ url }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Request failed.");
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Request failed.");
    } finally {
      setLoading(false);
    }
  }

  const statusTone = !result
    ? ""
    : result.status < 300
      ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
      : result.status < 400
        ? "border-blue-500/30 bg-blue-500/10 text-blue-300"
        : "border-red-500/30 bg-red-500/10 text-red-300";

  return (
    <div className="space-y-5">
      <form onSubmit={run} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="URL" hint="Redirects are reported, not followed. https:// assumed if omitted.">
            <input
              className="input"
              placeholder="https://example.com"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit">
          Fetch headers
        </RunButton>
      </form>

      <ErrorNote>{error}</ErrorNote>

      {result && (
        <ResultCard title={result.url}>
          <div className="mb-3 flex flex-wrap items-center gap-2">
            <span className={`inline-flex rounded-full border px-3 py-1 text-sm font-semibold ${statusTone}`}>
              {result.status} {result.statusText}
            </span>
            {result.redirect && (
              <span className="text-sm text-slate-400">
                → <span className="font-mono text-[13px] text-slate-300">{result.redirect}</span>
              </span>
            )}
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <tbody>
                {result.headers.map(([k, v], i) => (
                  <tr key={i} className="border-t border-white/[0.05]">
                    <td className="py-1.5 pr-4 align-top font-mono text-[13px] text-brand-300">{k}</td>
                    <td className="py-1.5 align-top font-mono text-[13px] break-all text-slate-300">{v}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </ResultCard>
      )}
    </div>
  );
}

