"use client";

import { useEffect, useState } from "react";
import { CopyButton } from "./ui";

const ALGOS = ["SHA-1", "SHA-256", "SHA-384", "SHA-512"] as const;
type Algo = (typeof ALGOS)[number];

function toHex(buf: ArrayBuffer): string {
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export function HashGeneratorTool() {
  const [input, setInput] = useState("");
  const [hashes, setHashes] = useState<Record<Algo, string>>({
    "SHA-1": "",
    "SHA-256": "",
    "SHA-384": "",
    "SHA-512": "",
  });

  useEffect(() => {
    let alive = true;
    if (!input) {
      setHashes({ "SHA-1": "", "SHA-256": "", "SHA-384": "", "SHA-512": "" });
      return;
    }
    const data = new TextEncoder().encode(input);
    Promise.all(ALGOS.map((a) => crypto.subtle.digest(a, data).then((d) => [a, toHex(d)] as const))).then((pairs) => {
      if (!alive) return;
      const next = {} as Record<Algo, string>;
      for (const [a, h] of pairs) next[a] = h;
      setHashes(next);
    });
    return () => {
      alive = false;
    };
  }, [input]);

  return (
    <div className="space-y-4">
      <div>
