export function toolsByCategory(): Record<ToolCategory, Tool[]> {
  const out: Record<ToolCategory, Tool[]> = { Network: [], Developer: [], Security: [] };
  for (const t of TOOLS) out[t.category].push(t);
  return out;
}

/** Small related-tools helper for a given slug (same category, excluding self). */
export function relatedTools(slug: string, limit = 4): { label: string; href: string }[] {
  const self = TOOLS.find((t) => t.slug === slug);
  if (!self) return [];
  const same = TOOLS.filter((t) => t.slug !== slug && t.category === self.category);
  const rest = TOOLS.filter((t) => t.slug !== slug && t.category !== self.category);
  return [...same, ...rest].slice(0, limit).map((t) => ({ label: t.name, href: `/tools/${t.slug}` }));
}

