"use client";

import { useState } from "react";
import { CopyButton, ErrorNote } from "./ui";

/** UTF-8 safe base64 using TextEncoder/Decoder. */
function encode(str: string): string {
  const bytes = new TextEncoder().encode(str);
  let bin = "";
  bytes.forEach((b) => (bin += String.fromCharCode(b)));
  return btoa(bin);
}
function decode(b64: string): string {
  const bin = atob(b64.trim());
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

export function Base64Tool() {
  const [mode, setMode] = useState<"encode" | "decode">("encode");
  const [input, setInput] = useState("");

  // Derive output and error purely from state — no render-phase setState.
  let output = "";
  let error = "";
  if (input) {
    try {
      output = mode === "encode" ? encode(input) : decode(input);
    } catch {
      if (mode === "decode") error = "Input is not valid Base64.";
    }
  }

  return (
    <div className="space-y-4">
      <div className="inline-flex rounded-xl border border-white/10 bg-white/[0.03] p-1">
        {(["encode", "decode"] as const).map((m) => (
          <button
            key={m}
            type="button"
            onClick={() => setMode(m)}
            className={`rounded-lg px-4 py-1.5 text-sm font-medium capitalize transition-colors ${
              mode === m ? "bg-brand-500/20 text-white" : "text-slate-400 hover:text-white"
            }`}
          >
            {m}
          </button>
        ))}
      </div>

      <div>
        <span className="label">{mode === "encode" ? "Text to encode" : "Base64 to decode"}</span>
        <textarea
          className="input min-h-[120px] font-mono"
          placeholder={mode === "encode" ? "Hello, world!" : "SGVsbG8sIHdvcmxkIQ=="}
          value={input}
          onChange={(e) => setInput(e.target.value)}
          spellCheck={false}
        />
      </div>

      <ErrorNote>{error}</ErrorNote>

      <div>
        <div className="mb-1.5 flex items-center justify-between">
          <span className="label mb-0">Result</span>
          <CopyButton value={output} />
        </div>
        <textarea
          readOnly
          className="input min-h-[120px] font-mono text-slate-300"
          value={output}
          placeholder="Output appears here"
        />
      </div>
    </div>
  );
}

